#include <stdio.h>
#define M 5
int q[M], front = 0, rear = 0;
void EnQueue(int x) { q[rear] = x; rear = (rear + 1) % M; }
int DeQueue(void) { int x = q[front]; front = (front + 1) % M; return x; }

int main(void)
{
    EnQueue(1); EnQueue(2); EnQueue(3);
    DeQueue(); DeQueue();
    EnQueue(4); EnQueue(5); EnQueue(6);
    printf("%d %d\n", front, rear);
    return 0;
}
